/* Free-TV Player — vanilla JS app. No frameworks, no build step required.
 * Data modules (app/data/*.js) are generated by scripts/build_catalog.py and
 * lazy-loaded per view; the single-file bundle (dist/index.html) pre-inlines
 * them and this code picks that up automatically. */
(() => {
  "use strict";

  const $ = (sel) => document.querySelector(sel);
  const el = (tag, cls, text) => {
    const node = document.createElement(tag);
    if (cls) node.className = cls;
    if (text != null) node.textContent = text;
    return node;
  };
  const normalize = (s) =>
    (s || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();
  const debounce = (fn, ms) => {
    let t;
    return (...args) => {
      clearTimeout(t);
      t = setTimeout(() => fn(...args), ms);
    };
  };
  const hashOf = (s) => {
    let h = 0;
    for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0;
    return h;
  };
  const TAG_LABELS = {
    geo: "geo-blocked", sd: "SD", youtube: "YouTube", twitch: "Twitch",
    not247: "not 24/7", vpn: "VPN",
  };
  const EMBED_APP = {
    name: "eBuzz · AI Studio app",
    url: "https://ai.studio/apps/5d188f2a-5162-4288-a32e-990a76df807a",
  };

  /* ------------------------------------------------------------------ *
   * data loading (lazy per view; skips network when bundled inline)
   * ------------------------------------------------------------------ */
  const channelsStore = window.FREETV_CHANNELS || {};

  function loadScript(src) {
    return new Promise((resolve, reject) => {
      const s = document.createElement("script");
      s.src = src;
      s.onload = resolve;
      s.onerror = () => reject(new Error("Failed to load " + src));
      document.head.appendChild(s);
    });
  }
  async function ensureCatalog() {
    if (window.FREETV_CATALOG) return window.FREETV_CATALOG;
    await loadScript("data/catalog.js");
    if (!window.FREETV_CATALOG) throw new Error("catalog.js did not define FREETV_CATALOG");
    return window.FREETV_CATALOG;
  }
  async function ensureChannels(key) {
    if (channelsStore[key]) return channelsStore[key];
    const file = key === "__all" ? "data/channels-all.js" : "data/channels-" + key + ".js";
    await loadScript(file);
    if (!channelsStore[key]) channelsStore[key] = [];
    return channelsStore[key];
  }

  /* ------------------------------------------------------------------ *
   * state + hash router   (#/  #/c/<code>  #/k/<key>  #/search/<q>)
   * ------------------------------------------------------------------ */
  const state = {
    view: { kind: "home" },
    current: null, // { key, channels, q, group } for the active list view
  };
  let renderToken = 0;
  const view = $("#view");

  function parseRoute() {
    const h = location.hash.replace(/^#\/?/, "");
    if (!h) return { kind: "home" };
    const head = h.split("/")[0];
    const arg = decodeURIComponent(h.slice(head.length + 1));
    if (head === "c" && arg) return { kind: "country", code: arg.toLowerCase() };
    if (head === "k" && arg) return { kind: "list", key: arg };
    if (head === "app") return { kind: "embed" };
    if (head === "search" && arg) return { kind: "search", q: arg };
    return { kind: "home" };
  }
  window.addEventListener("hashchange", () => {
    state.view = parseRoute();
    render().catch(showFatal);
  });

  function showFatal(err) {
    view.replaceChildren(el("p", "error", "Failed to load catalog data: " + err.message));
  }

  async function render() {
    await ensureCatalog();
    syncSearchInput();
    paintStats();
    paintSidebar();
    const r = state.view;
    if (r.kind === "country") return renderList({ code: r.code });
    if (r.kind === "list") return renderList({ key: r.key });
    if (r.kind === "embed") return renderEmbed();
    if (r.kind === "search") return renderSearch(r.q);
    return renderHome();
  }

  /* ------------------------------------------------------------------ *
   * chrome: stats + sidebar
   * ------------------------------------------------------------------ */
  function statChip(value, label) {
    const s = el("span", "stat");
    s.append(el("b", null, value));
    if (label) s.append(el("span", null, label));
    return s;
  }
  function paintStats() {
    const c = window.FREETV_CATALOG;
    const stats = $("#stats");
    stats.replaceChildren(
      statChip(c.stats.channels.toLocaleString("en-US"), "channels"),
      statChip(String(c.stats.countries), "countries"),
      statChip(c.stats.ftv.toLocaleString("en-US"), "curated · Free-TV"),
      statChip(c.stats.org.toLocaleString("en-US"), "indexed · iptv-org"),
      statChip("updated " + c.generatedAt, "")
    );
  }
  function paintSidebar() {
    const c = window.FREETV_CATALOG;
    const cul = $("#nav-countries");
    const cfrag = document.createDocumentFragment();
    for (const country of c.countries) {
      const li = el("li");
      const a = el("a");
      a.href = "#/c/" + country.code;
      const img = document.createElement("img");
      img.src = country.flag;
      img.alt = "";
      img.loading = "lazy";
      img.width = 18;
      img.height = 18;
      img.onerror = () => img.replaceWith(el("span", "flag-fallback sm", country.code.toUpperCase()));
      a.append(img, el("span", "nav-name", country.name),
        el("span", "nav-count", country.total.toLocaleString("en-US")));
      if (state.view.kind === "country" && state.view.code === country.code) a.classList.add("active");
      li.append(a);
      cfrag.append(li);
    }
    cul.replaceChildren(cfrag);

    const cl = $("#nav-cats");
    const kfrag = document.createDocumentFragment();
    for (const cat of c.categories) {
      const li = el("li");
      const a = el("a");
      a.href = "#/k/" + cat.key;
      a.append(el("span", "nav-name", cat.label), el("span", "nav-count", String(cat.count)));
      if (state.view.kind === "list" && state.view.key === cat.key) a.classList.add("active");
      li.append(a);
      kfrag.append(li);
    }
    cl.replaceChildren(kfrag);

    const appLink = document.getElementById("nav-app-link");
    if (appLink) appLink.classList.toggle("active", state.view.kind === "embed");
  }

  /* ------------------------------------------------------------------ *
   * artwork: deterministic initials tile when a logo is missing/broken
   * ------------------------------------------------------------------ */
  function escapeXml(s) {
    return s.replace(/[<>&"']/g, (ch) =>
      ({ "<": "&lt;", ">": "&gt;", "&": "&amp;", '"': "&quot;", "'": "&apos;" }[ch]));
  }
  function fallbackLogo(name) {
    const words = (name || "TV").split(/\s+/).filter(Boolean);
    const initials = words.slice(0, 2).map((w) => w[0]).join("").toUpperCase() || "TV";
    const hue = hashOf(name || "tv") % 360;
    const svg =
      '<svg xmlns="http://www.w3.org/2000/svg" width="96" height="96">' +
      '<rect width="96" height="96" rx="18" fill="hsl(' + hue + ',45%,32%)"/>' +
      '<text x="48" y="61" font-family="system-ui,sans-serif" font-size="38" font-weight="700" ' +
      'fill="hsl(' + hue + ',70%,85%)" text-anchor="middle">' + escapeXml(initials) + "</text></svg>";
    return "data:image/svg+xml;utf8," + encodeURIComponent(svg);
  }

  /* ------------------------------------------------------------------ *
   * channel cards
   * ------------------------------------------------------------------ */
  function channelCard(ch) {
    const card = el("button", "card");
    card.type = "button";
    card.addEventListener("click", () => openPlayer(ch));

    const img = document.createElement("img");
    img.className = "logo";
    img.alt = "";
    img.loading = "lazy";
    img.width = 44;
    img.height = 44;
    img.src = ch.l || fallbackLogo(ch.n);
    img.onerror = () => {
      img.onerror = null;
      img.src = fallbackLogo(ch.n);
    };

    const body = el("div", "card-body");
    body.append(el("span", "card-name", ch.n));
    body.append(el("span", "card-sub", [ch.g, ch.q].filter(Boolean).join(" · ") || "Live"));

    const badges = el("span", "badges");
    badges.append(el("span", "badge " + (ch.s === "ftv" ? "ftv" : "org"), ch.s === "ftv" ? "FTV" : "ORG"));
    for (const t of ch.t || []) badges.append(el("span", "tag", TAG_LABELS[t] || t));
    if (ch.y || /youtube\.com|youtu\.be|twitch\.tv/i.test(ch.u || "")) {
      badges.append(el("span", "tag", "▶ " + (/twitch/i.test(ch.u) ? "Twitch" : "YouTube")));
    }

    card.append(img, body, badges);
    return card;
  }

  /* ------------------------------------------------------------------ *
   * views
   * ------------------------------------------------------------------ */
  function notFound(msg) {
    const wrap = el("section", "list-header");
    const inner = el("div", "list-headline");
    inner.append(el("h1", null, "Not found"), el("p", "muted", msg));
    const home = el("a", "btn ghost", "← Back to home");
    home.href = "#/";
    wrap.append(inner, home);
    return wrap;
  }

  function renderHome() {
    const c = window.FREETV_CATALOG;
    const frag = document.createDocumentFragment();

    const hero = el("section", "hero");
    hero.append(
      el("h1", null, "Free live TV, catalogued."),
      el("p", "muted",
        "Browse, search and play thousands of publicly listed free channels aggregated from two " +
        "community playlists — Free-TV (human-curated) and iptv-org (per-country streams). " +
        "Nothing is hosted here; playback uses the original stream URLs."),
    );
    const actions = el("div", "hero-actions");
    const browse = el("a", "btn", "Browse countries");
    browse.href = "#countries";
    browse.addEventListener("click", (e) => {
      e.preventDefault();
      $("#countries").scrollIntoView({ behavior: "smooth" });
    });
    const random = el("button", "btn ghost", "Play a random channel");
    random.type = "button";
    random.addEventListener("click", playRandom);
    actions.append(browse, random);
    hero.append(actions);
    frag.append(hero);

    if (c.categories.length) {
      const catSec = el("section", "section");
      catSec.append(el("h2", null, "Categories"));
      const chips = el("div", "chip-row");
      for (const cat of c.categories) {
        const a = el("a", "chip", cat.label + " · " + cat.count);
        a.href = "#/k/" + cat.key;
        chips.append(a);
      }
      catSec.append(chips);
      frag.append(catSec);
    }

    const featSec = el("section", "section");
    featSec.append(el("h2", null, "Featured · Free-TV curated"));
    const featGrid = el("div", "card-grid");
    for (const ch of c.featured.slice(0, 28)) featGrid.append(channelCard(ch));
    featSec.append(featGrid);
    frag.append(featSec);

    const cSec = el("section", "section");
    cSec.id = "countries";
    cSec.append(el("h2", null, "Countries"));
    const grid = el("div", "country-grid");
    for (const country of c.countries) {
      const a = el("a", "country-card");
      a.href = "#/c/" + country.code;
      const line = el("span", "country-line");
      const img = document.createElement("img");
      img.src = country.flag;
      img.alt = "";
      img.loading = "lazy";
      img.width = 28;
      img.height = 28;
      img.onerror = () => img.replaceWith(el("span", "flag-fallback", country.code.toUpperCase()));
      line.append(img, el("span", "country-name", country.name));
      a.append(line, el("span", "country-count", country.total.toLocaleString("en-US")));
      if (country.ftv) a.append(el("span", "badge ftv", "curated"));
      grid.append(a);
    }
    cSec.append(grid);
    frag.append(cSec);
    view.replaceChildren(frag);
  }

  async function renderList(opts) {
    const token = ++renderToken;
    const c = window.FREETV_CATALOG;
    let key, title, flag = null;
    const metaBits = [];
    if (opts.code) {
      const country = c.countries.find((x) => x.code === opts.code);
      if (!country) {
        view.replaceChildren(notFound("Unknown country: " + opts.code));
        return;
      }
      key = country.code;
      title = country.name;
      flag = country.flag;
      metaBits.push(country.total.toLocaleString("en-US") + " channels");
      if (country.ftv) metaBits.push(country.ftv + " curated");
      if (country.org) metaBits.push(country.org + " indexed");
    } else {
      const cat = c.categories.find((x) => x.key === opts.key);
      if (!cat) {
        view.replaceChildren(notFound("Unknown list: " + opts.key));
        return;
      }
      key = cat.key;
      title = cat.label;
      metaBits.push(cat.count + " channels");
    }

    state.current = { key, channels: null, q: "", group: "" };

    const header = el("section", "list-header");
    if (flag) {
      const img = document.createElement("img");
      img.className = "page-flag";
      img.src = flag;
      img.alt = "";
      img.width = 40;
      img.height = 40;
      img.onerror = () => img.replaceWith(el("span", "flag-fallback", key.toUpperCase()));
      header.append(img);
    }
    const headline = el("div", "list-headline");
    headline.append(el("h1", null, title), el("p", "muted", metaBits.join(" · ")));
    header.append(headline);
    const copyBtn = el("button", "btn ghost", "Copy M3U");
    copyBtn.type = "button";
    header.append(copyBtn);

    view.replaceChildren(header, buildFilterBar(), el("div", "card-grid"));

    const channels = await ensureChannels(key);
    if (token !== renderToken) return; // superseded by a newer navigation
    state.current.channels = channels;
    copyBtn.addEventListener("click", () => {
      try {
        navigator.clipboard.writeText(copyM3U(channels)).then(() => {
          copyBtn.textContent = "Copied ✓";
          setTimeout(() => (copyBtn.textContent = "Copy M3U"), 1600);
        });
      } catch {
        copyBtn.textContent = "Clipboard blocked";
      }
    });
    paintGroupChips(channels);
    paintCurrent();
  }

  async function renderSearch(q) {
    const token = ++renderToken;
    const header = el("section", "list-header");
    const headline = el("div", "list-headline");
    headline.append(el("h1", null, 'Search: "' + q + '"'));
    header.append(headline);
    const grid = el("div", "card-grid");
    view.replaceChildren(header, grid);

    const all = await ensureChannels("__all");
    if (token !== renderToken) return;
    const terms = normalize(q).split(/\s+/).filter(Boolean);
    const hits = all.filter((ch) => {
      const hay = normalize(ch.n + " " + (ch.g || "") + " " + (ch.id || ""));
      return terms.every((t) => hay.includes(t));
    });
    headline.append(el("p", "muted",
      hits.length.toLocaleString("en-US") + " matching channels across both sources"));
    const frag = document.createDocumentFragment();
    for (const ch of hits.slice(0, 600)) frag.append(channelCard(ch));
    grid.replaceChildren(frag);
  }

  /* ------------------------------------------------------------------ *
   * embedded AI Studio app (iframe panel + launch-card fallback)
   * ------------------------------------------------------------------ */
  function renderEmbed() {
    const frag = document.createDocumentFragment();

    const header = el("section", "list-header");
    const headline = el("div", "list-headline");
    headline.append(el("h1", null, EMBED_APP.name));
    headline.append(el("p", "muted",
      "The companion web app, embedded below. If the panel stays blank or is refused, " +
      "Google blocks framing or requires sign-in — use the launch button."));
    header.append(headline);
    const launch = el("a", "btn", "Open app ↗");
    launch.href = EMBED_APP.url;
    launch.target = "_blank";
    launch.rel = "noopener noreferrer";
    header.append(launch);
    frag.append(header);

    const stage = el("div", "embed-stage");
    const frame = document.createElement("iframe");
    frame.src = EMBED_APP.url;
    frame.title = EMBED_APP.name;
    frame.loading = "lazy";
    frame.referrerPolicy = "no-referrer";
    frame.allow = "clipboard-write; fullscreen";
    stage.append(frame);
    frag.append(stage);

    frag.append(el("p", "muted small embed-note",
      "Embedding note: ai.studio is served by Google and may send anti-framing headers " +
      "(X-Frame-Options / frame-ancestors) or redirect to a sign-in page; in that case the " +
      "browser refuses to render it inside this panel — the launch button above opens the " +
      "app in a new tab instead."));
    view.replaceChildren(frag);
  }

  /* ------------------------------------------------------------------ *
   * in-list filter + group chips
   * ------------------------------------------------------------------ */
  function buildFilterBar() {
    const bar = el("div", "list-filter");
    const input = document.createElement("input");
    input.type = "search";
    input.placeholder = "Filter this list…";
    input.autocomplete = "off";
    input.setAttribute("aria-label", "Filter channels in this list");
    input.addEventListener("input", debounce(() => {
      state.current.q = input.value;
      paintCurrent();
    }, 150));
    const chips = el("div", "group-chips");
    chips.id = "group-chips";
    const count = el("span", "muted small");
    count.id = "list-count";
    bar.append(input, chips, count);
    return bar;
  }

  function chipBtn(label, active) {
    const b = el("button", "chip" + (active ? " active" : ""), label);
    b.type = "button";
    return b;
  }

  function paintGroupChips(channels) {
    const box = $("#group-chips");
    if (!box) return;
    const counts = new Map();
    for (const ch of channels) {
      const g = ch.g || "Other";
      counts.set(g, (counts.get(g) || 0) + 1);
    }
    if (counts.size < 2) {
      box.hidden = true;
      box.replaceChildren();
      return;
    }
    box.hidden = false;
    const top = [...counts.entries()].sort((a, b) => b[1] - a[1]).slice(0, 14);
    box.replaceChildren();
    const all = chipBtn("All groups", !state.current.group);
    all.addEventListener("click", () => {
      state.current.group = "";
      paintGroupChips(channels);
      paintCurrent();
    });
    box.append(all);
    for (const [g, n] of top) {
      const b = chipBtn(g + " · " + n, state.current.group === g);
      b.addEventListener("click", () => {
        state.current.group = state.current.group === g ? "" : g;
        paintGroupChips(channels);
        paintCurrent();
      });
      box.append(b);
    }
    if (counts.size > 14) box.append(el("span", "muted small", "+" + (counts.size - 14) + " more groups"));
  }

  function paintCurrent() {
    const cur = state.current;
    if (!cur || !cur.channels) return;
    let shown = cur.channels;
    if (cur.group) shown = shown.filter((ch) => (ch.g || "") === cur.group);
    if (cur.q) {
      const nq = normalize(cur.q);
      shown = shown.filter((ch) =>
        normalize(ch.n + " " + (ch.id || "") + " " + (ch.g || "")).includes(nq));
    }
    const grid = $("#view .card-grid");
    if (!grid) return;
    const frag = document.createDocumentFragment();
    for (const ch of shown.slice(0, 600)) frag.append(channelCard(ch));
    grid.replaceChildren(frag);
    const count = $("#list-count");
    if (count) {
      count.textContent = shown.length === 0
        ? "No channel matches."
        : shown.length.toLocaleString("en-US") + " channels" +
          (shown.length > 600 ? " · showing first 600" : "");
    }
  }

  /* ------------------------------------------------------------------ *
   * M3U export (clipboard) — links out, never re-hosts
   * ------------------------------------------------------------------ */
  function copyM3U(channels) {
    const lines = ["#EXTM3U"];
    for (const ch of channels) {
      const attrs = ['tvg-name="' + (ch.r || ch.n) + '"'];
      if (ch.l) attrs.push('tvg-logo="' + ch.l + '"');
      if (ch.id) attrs.push('tvg-id="' + ch.id + '"');
      if (ch.c) attrs.push('tvg-country="' + ch.c.toUpperCase() + '"');
      if (ch.g) attrs.push('group-title="' + ch.g + '"');
      lines.push("#EXTINF:-1 " + attrs.join(" ") + "," + ch.n, ch.u);
    }
    return lines.join("\n");
  }

  function playRandom() {
    const pool = (state.current && state.current.channels && state.current.channels.length)
      ? state.current.channels
      : window.FREETV_CATALOG.featured;
    openPlayer(pool[Math.floor(Math.random() * pool.length)]);
  }

  /* ------------------------------------------------------------------ *
   * player modal (hls.js when available, native HLS/MP4 otherwise)
   * ------------------------------------------------------------------ */
  let hls = null;
  let currentChannel = null;

  function setStatus(text) {
    $("#pl-status").textContent = text || "";
  }
  function showFallback(text, linkText) {
    $("#video").hidden = true;
    const fb = $("#player-fallback");
    fb.hidden = false;
    $("#player-fallback-text").textContent = text;
    const btn = $("#player-fallback-btn");
    if (linkText) {
      btn.hidden = false;
      btn.textContent = linkText;
      btn.onclick = () => window.open(currentChannel.u, "_blank", "noopener");
    } else {
      btn.hidden = true;
    }
  }
  function clearFallback() {
    $("#video").hidden = false;
    $("#player-fallback").hidden = true;
    setStatus("");
  }

  function openPlayer(ch) {
    currentChannel = ch;
    $("#player-modal").hidden = false;
    document.body.classList.add("no-scroll");
    $("#pl-name").textContent = ch.n;
    $("#pl-meta").textContent = [
      ch.g, ch.q,
      ch.s === "ftv" ? "Free-TV curated" : "iptv-org",
      ch.c ? ch.c.toUpperCase() : null,
    ].filter(Boolean).join(" · ");
    const logo = $("#pl-logo");
    logo.src = ch.l || fallbackLogo(ch.n);
    logo.onerror = () => {
      logo.onerror = null;
      logo.src = fallbackLogo(ch.n);
    };
    const raw = $("#pl-raw");
    if (ch.u) raw.href = ch.u;
    else raw.removeAttribute("href");
    clearFallback();

    const url = ch.u || "";
    const video = $("#video");

    if (!url) {
      showFallback("No stream URL on record for this channel.");
      return;
    }
    if (ch.y || /youtube\.com|youtu\.be|twitch\.tv/i.test(url)) {
      showFallback(
        "This channel is distributed through " +
        (/twitch/i.test(url) ? "Twitch" : "YouTube") +
        ", which blocks direct embedding. Open it on the provider's page:",
        "Open on provider ↗");
      return;
    }
    if (/\.mpd(\?|$)/i.test(url)) {
      showFallback(
        "This is an MPEG-DASH stream, which browsers here cannot play directly. " +
        "Copy the URL into VLC, ffmpeg or any DASH-capable player:");
      return;
    }
    if (window.Hls && window.Hls.isSupported()) {
      setStatus("Loading stream…");
      hls = new Hls({ maxBufferLength: 20 });
      hls.loadSource(url);
      hls.attachMedia(video);
      hls.on(Hls.Events.MANIFEST_PARSED, () => {
        setStatus("");
        video.play().catch(() => setStatus("Press play to start."));
      });
      hls.on(Hls.Events.ERROR, (_, data) => {
        if (data.fatal) {
          setStatus("Stream error: " + data.details + " — it may be offline or geo-restricted.");
        }
      });
    } else if (video.canPlayType("application/vnd.apple.mpegurl")) {
      video.src = url;
      video.play().catch(() => {});
      video.addEventListener("error", () =>
        setStatus("The browser could not open this stream (offline or geo-restricted)."), { once: true });
    } else {
      showFallback("This browser cannot play HLS without hls.js, which failed to load.");
    }
  }

  function closePlayer() {
    if (hls) {
      hls.destroy();
      hls = null;
    }
    const video = $("#video");
    video.pause();
    video.removeAttribute("src");
    video.load();
    $("#player-modal").hidden = true;
    document.body.classList.remove("no-scroll");
  }

  for (const node of document.querySelectorAll("[data-close]")) {
    node.addEventListener("click", closePlayer);
  }
  $("#pl-copy").addEventListener("click", () => {
    if (!currentChannel) return;
    try {
      const entry = copyM3U([currentChannel]).replace("#EXTM3U\n", "");
      navigator.clipboard.writeText(entry).then(() => setStatus("Copied ✓"));
    } catch {
      setStatus("Clipboard unavailable");
    }
  });
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && !$("#player-modal").hidden) closePlayer();
    if (e.key === "/" && !/input|textarea|select/i.test(document.activeElement.tagName)) {
      e.preventDefault();
      $("#global-search").focus();
    }
  });

  /* ------------------------------------------------------------------ *
   * global search + theme
   * ------------------------------------------------------------------ */
  const searchInput = $("#global-search");
  searchInput.addEventListener("input", debounce(() => {
    const q = searchInput.value.trim();
    if (q.length >= 2) {
      const target = "#/search/" + encodeURIComponent(q);
      if (location.hash !== target) location.hash = target;
    } else if (!q && state.view.kind === "search") {
      location.hash = "#/";
    }
  }, 250));
  function syncSearchInput() {
    if (state.view.kind === "search") searchInput.value = state.view.q;
  }

  function applyTheme(t) {
    document.documentElement.dataset.theme = t;
    try {
      localStorage.setItem("ftv-theme", t);
    } catch { /* private mode */ }
  }
  let theme = "dark";
  try {
    theme = localStorage.getItem("ftv-theme") ||
      (matchMedia("(prefers-color-scheme: light)").matches ? "light" : "dark");
  } catch { /* storage blocked */ }
  applyTheme(theme);
  $("#theme-toggle").addEventListener("click", () =>
    applyTheme(document.documentElement.dataset.theme === "dark" ? "light" : "dark"));

  /* ------------------------------------------------------------------ *
   * boot
   * ------------------------------------------------------------------ */
  if (!location.hash) history.replaceState(null, "", "#/");
  state.view = parseRoute();
  render().catch(showFatal);
})();
